from __future__ import annotations

from html import escape


STYLE = r"""
:root{color-scheme:light;--bg:#f5f7fb;--card:#fff;--soft:#f8f9fd;--text:#131827;--muted:#6c7385;--line:#e5e8f0;--accent:#6558e8;--accent2:#8b5cf6;--good:#16845b;--warn:#a96800;--bad:#c7334d;--shadow:0 18px 50px rgba(35,40,70,.08)}
*{box-sizing:border-box}html{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}body{margin:0;min-height:100vh;background:radial-gradient(circle at 12% -8%,rgba(101,88,232,.13),transparent 31%),radial-gradient(circle at 100% 0,rgba(139,92,246,.1),transparent 34%),var(--bg)}button,input,select{font:inherit}.shell{width:min(1160px,calc(100% - 28px));margin:auto;padding:22px 0 64px}.top{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:12px}.logo{width:44px;height:44px;border-radius:15px;display:grid;place-items:center;color:#fff;font-weight:850;background:linear-gradient(145deg,var(--accent),var(--accent2));box-shadow:0 12px 30px rgba(101,88,232,.28)}h1,h2,h3,p{margin-top:0}.brand h1{font-size:20px;margin:0}.brand p{font-size:12px;color:var(--muted);margin:3px 0 0}.pill{display:inline-flex;align-items:center;gap:7px;padding:9px 12px;border-radius:999px;background:rgba(255,255,255,.84);border:1px solid var(--line);color:var(--muted);font-size:13px}.dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 0 5px rgba(22,132,91,.1)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:22px;padding:21px;box-shadow:var(--shadow)}.hero{grid-column:span 12;display:flex;justify-content:space-between;align-items:flex-end;gap:20px}.hero h2{font-size:clamp(30px,5vw,52px);line-height:1.05;letter-spacing:-.045em;margin:10px 0 12px}.hero p{color:var(--muted);line-height:1.7;max-width:660px;margin:0}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;color:var(--accent)}.actions{display:flex;gap:10px;flex-wrap:wrap}.btn{border:0;border-radius:14px;padding:11px 15px;font-weight:750;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px;cursor:pointer}.btn.primary{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;box-shadow:0 10px 22px rgba(101,88,232,.22)}.btn.secondary{background:var(--soft);color:var(--text);border:1px solid var(--line)}.stats{grid-column:span 12;display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:17px}.stat .label{font-size:12px;color:var(--muted)}.stat .value{font-size:22px;font-weight:820;margin-top:8px;letter-spacing:-.03em}.lottery{grid-column:span 6}.lottery-head{display:flex;justify-content:space-between;gap:12px}.lottery h3{font-size:22px;margin-bottom:4px}.sub{font-size:12px;color:var(--muted);line-height:1.55}.numbers{display:flex;flex-wrap:wrap;gap:7px;margin:17px 0}.num{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:var(--soft);border:1px solid var(--line);font-weight:780}.forecast{padding:13px 0;border-top:1px solid var(--line)}.forecast-title{display:flex;justify-content:space-between;gap:12px;font-size:14px;font-weight:750}.good{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:18px}.sidebar{position:sticky;top:18px;height:max-content;background:rgba(255,255,255,.88);border:1px solid var(--line);border-radius:20px;padding:10px;box-shadow:var(--shadow)}.nav{width:100%;border:0;background:transparent;color:var(--muted);text-align:left;padding:13px 14px;border-radius:13px;font-weight:760;cursor:pointer}.nav.active{background:#efefff;color:var(--accent)}.panel{display:none}.panel.active{display:block}.panel-head{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;margin-bottom:15px}.panel-head h2{font-size:28px;letter-spacing:-.035em;margin-bottom:4px}.panel-head p{color:var(--muted);margin:0}.form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:12px;color:var(--muted);font-weight:760}.input{width:100%;padding:12px 13px;border-radius:14px;border:1px solid var(--line);background:var(--soft);outline:none;color:var(--text)}.input:focus{border-color:rgba(101,88,232,.55);box-shadow:0 0 0 4px rgba(101,88,232,.1);background:#fff}.switch-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:15px;border:1px solid var(--line);border-radius:16px;background:var(--soft)}.switch{position:relative;width:48px;height:28px}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;border-radius:999px;background:#c7ccd8;transition:.18s}.slider:before{content:"";position:absolute;width:22px;height:22px;left:3px;top:3px;border-radius:50%;background:#fff;box-shadow:0 3px 8px rgba(0,0,0,.16);transition:.18s}.switch input:checked+.slider{background:var(--accent)}.switch input:checked+.slider:before{transform:translateX(20px)}.chips{display:flex;gap:8px;flex-wrap:wrap}.chip{border:1px solid var(--line);background:var(--soft);border-radius:999px;padding:8px 11px;font-size:12px;font-weight:760;color:var(--muted);cursor:pointer}.notice{padding:13px 14px;border-radius:14px;background:#f0f1ff;border:1px solid #dfe0ff;color:#4b4cbb;font-size:12px;line-height:1.65}.log{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;word-break:break-word;background:#121725;color:#dce2f7;border-radius:16px;padding:15px;min-height:80px;font-size:12px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top}.table th{color:var(--muted)}.toast{position:fixed;right:18px;bottom:18px;max-width:min(420px,calc(100% - 36px));background:#151a29;color:#fff;padding:13px 15px;border-radius:14px;box-shadow:0 18px 45px rgba(0,0,0,.24);opacity:0;transform:translateY(10px);pointer-events:none;transition:.18s;z-index:100}.toast.show{opacity:1;transform:none}.toast.error{background:#7a2637}.login-wrap{min-height:100vh;display:grid;place-items:center;padding:22px}.login-card{width:min(430px,100%);background:rgba(255,255,255,.92);border:1px solid var(--line);border-radius:28px;padding:28px;box-shadow:0 26px 80px rgba(35,40,70,.14)}.login-card h1{font-size:30px;margin:18px 0 8px;letter-spacing:-.04em}.login-card p{color:var(--muted);line-height:1.65}.login-card .btn{width:100%;margin-top:13px}.footer{text-align:center;color:var(--muted);font-size:12px;line-height:1.7;margin-top:24px}.mobile{display:none}
@media(max-width:860px){.shell{width:min(100% - 20px,720px);padding-top:16px}.hero{flex-direction:column;align-items:flex-start}.stats{grid-template-columns:1fr 1fr}.lottery{grid-column:span 12}.layout{display:block}.sidebar{display:none}.mobile{display:grid;grid-template-columns:repeat(4,1fr);position:fixed;left:9px;right:9px;bottom:9px;z-index:80;background:rgba(255,255,255,.94);border:1px solid var(--line);border-radius:18px;padding:6px;box-shadow:0 18px 50px rgba(35,40,70,.2)}.mobile .nav{text-align:center;font-size:12px;padding:10px 3px}.admin-shell{padding-bottom:96px}.form{grid-template-columns:1fr}.field.full{grid-column:auto}.panel-head{align-items:flex-start;flex-direction:column}}
@media(max-width:520px){.stats{grid-template-columns:1fr}.card{padding:18px}.hero h2{font-size:32px}.top .pill.hide-small{display:none}.actions{width:100%}.actions .btn{flex:1}.num{width:31px;height:31px}}
"""


def _document(title: str, body: str, script: str = "") -> str:
    template = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f7fb"><title>__TITLE__</title><style>__STYLE__</style></head><body>__BODY__<div class="toast" id="toast"></div><script>__SCRIPT__</script></body></html>"""
    return (
        template.replace("__TITLE__", escape(title))
        .replace("__STYLE__", STYLE)
        .replace("__BODY__", body)
        .replace("__SCRIPT__", script)
    )


def public_page() -> str:
    body = """
<div class="shell">
  <header class="top"><div class="brand"><div class="logo">天</div><div><h1>天机云端</h1><p>持续同步、首次冻结与真实验证</p></div></div><div class="pill"><span class="dot" id="statusDot"></span><span id="statusText">连接中</span></div></header>
  <div class="grid">
    <section class="card hero"><div><div class="eyebrow">Tianji Cloud</div><h2>服务器持续运行，<br>手机保留本地能力。</h2><p>云端全天同步开奖并保存前向档案；服务器失效时，Android 仍可使用本机统计、手机直连 AI 和本地历史。</p></div><div class="actions"><a class="btn primary" href="/admin">管理控制台</a><a class="btn secondary" href="/docs">API 文档</a></div></section>
    <section class="stats" id="stats"></section>
    <div id="lotteries" style="display:contents"></div>
  </div>
  <div class="footer">随机开奖不可可靠预测。本服务只用于统计实验、首次冻结与目标期验证，不承诺盈利或必中。</div>
</div>
"""
    script = r"""
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt=n=>n?new Date(n).toLocaleString('zh-CN',{hour12:false}):'—';
async function refresh(){
  try{
    const r=await fetch('/v1/public/overview',{cache:'no-store'}); if(!r.ok) throw new Error('HTTP '+r.status); const d=await r.json();
    statusText.textContent=d.health.status==='ok'?'运行正常':'状态异常'; statusDot.style.background=d.health.status==='ok'?'var(--good)':'var(--bad)';
    stats.innerHTML=`<div class="stat"><div class="label">服务状态</div><div class="value good">${esc(d.health.database)}</div></div><div class="stat"><div class="label">后台任务</div><div class="value ${d.health.worker==='ok'?'good':'warn'}">${esc(d.health.worker)}</div></div><div class="stat"><div class="label">云端 AI</div><div class="value">${d.ai.configured?esc(d.ai.model):'未配置'}</div></div><div class="stat"><div class="label">服务版本</div><div class="value">${esc(d.health.version)}</div></div>`;
    lotteries.innerHTML=d.lotteries.map(x=>`<section class="card lottery"><div class="lottery-head"><div><h3>${esc(x.name)}</h3><div class="sub">最新期 ${esc(x.latest_period||'等待同步')} · ${fmt(x.synced_at_epoch_ms)}</div></div><div class="pill">目标期 ${esc(x.next_period||'待同步')}</div></div><div class="numbers">${(x.numbers||[]).map(n=>`<span class="num">${n}</span>`).join('')}</div>${x.forecasts.length?x.forecasts.map(f=>`<div class="forecast"><div class="forecast-title"><span>${f.source==='ai'?'云端 AI':'本机云端'} · 第 ${f.position+1} 名</span><span>${f.top6_hit===true?'命中':f.top6_hit===false?'未中':'待开奖'}</span></div><div class="sub">六码 ${f.top6.join(' ')} · 模型 ${esc(f.model)} · 目标期 ${esc(f.target_period)}</div></div>`).join(''):'<div class="sub">等待下一期前向档案</div>'}</section>`).join('');
  }catch(e){statusText.textContent='连接失败';statusDot.style.background='var(--bad)'}
}
refresh();setInterval(refresh,30000);
"""
    return _document("天机云端", body, script)


def login_page(configured: bool) -> str:
    message = "输入部署时设置的网页管理密码。" if configured else "服务器还没有设置管理密码，请重新运行升级脚本完成初始化。"
    disabled = "" if configured else "disabled"
    body = """
<div class="login-wrap"><main class="login-card"><div class="logo">天</div><h1>进入控制台</h1><p>__MESSAGE__</p><form id="loginForm"><div class="field"><label>管理密码</label><input class="input" id="password" type="password" minlength="8" autocomplete="current-password" placeholder="至少 8 个字符" __DISABLED__></div><button class="btn primary" id="loginBtn" __DISABLED__>登录</button></form><div class="footer"><a href="/" style="color:var(--accent);text-decoration:none">返回公开状态页</a></div></main></div>
""".replace("__MESSAGE__", escape(message)).replace("__DISABLED__", disabled)
    script = r"""
const toast=(m,e=false)=>{const t=document.getElementById('toast');t.textContent=m;t.className='toast show'+(e?' error':'');setTimeout(()=>t.className='toast',2600)};
document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('loginBtn');b.disabled=true;try{const r=await fetch('/admin/api/login',{method:'POST',headers:{'Content-Type':'application/json','X-Tianji-Admin':'1'},body:JSON.stringify({password:document.getElementById('password').value})});const d=await r.json();if(!r.ok)throw new Error(d.detail||'登录失败');location.href='/admin'}catch(err){toast(err.message,true);b.disabled=false}});
"""
    return _document("登录 · 天机控制台", body, script)


def admin_page() -> str:
    body = """
<div class="shell admin-shell">
<header class="top"><div class="brand"><div class="logo">天</div><div><h1>天机控制台</h1><p>无需 SSH 的云端管理面板</p></div></div><div class="actions"><div class="pill hide-small"><span class="dot" id="topDot"></span><span id="topStatus">读取中</span></div><button class="btn secondary" id="logoutBtn">退出</button></div></header>
<div class="layout"><aside class="sidebar"><button class="nav active" data-panel="overview">总览</button><button class="nav" data-panel="ai">AI 模型</button><button class="nav" data-panel="records">预测档案</button><button class="nav" data-panel="security">安全设置</button></aside><main>
<section class="panel active" id="panel-overview"><div class="panel-head"><div><h2>运行总览</h2><p>查看服务、数据库、后台任务与最近同步。</p></div><button class="btn primary" id="runBtn">立即执行一轮</button></div><div class="stats" id="adminStats"></div><div class="grid" id="adminLotteries" style="margin-top:16px"></div><div class="card" style="margin-top:16px"><h3>最近运行状态</h3><div class="log" id="runtimeLog">读取中…</div></div></section>
<section class="panel" id="panel-ai"><div class="panel-head"><div><h2>AI 模型</h2><p>保存后下一轮任务立即使用，不需要重启或 SSH。</p></div></div><div class="card"><div class="switch-row"><div><strong>启用云端 AI</strong><div class="sub">关闭后仍保留本机云端统计预测</div></div><label class="switch"><input id="aiEnabled" type="checkbox"><span class="slider"></span></label></div><div class="notice" style="margin:14px 0">API Key 不会完整回显。密钥输入框留空时会保留当前密钥。</div><div class="chips" style="margin-bottom:14px"><button class="chip" data-preset="deepseek-pro">DeepSeek V4 Pro</button><button class="chip" data-preset="deepseek-flash">DeepSeek V4 Flash</button><button class="chip" data-preset="deepseek-custom">DeepSeek 自定义</button><button class="chip" data-preset="openai">OpenAI Responses</button></div><div class="form"><div class="field full"><label>接口地址</label><input class="input" id="aiEndpoint" inputmode="url"></div><div class="field"><label>模型名</label><input class="input" id="aiModel" list="modelList"><datalist id="modelList"></datalist></div><div class="field"><label>超时时间</label><select class="input" id="aiTimeout"><option value="45">45 秒</option><option value="90">90 秒</option><option value="120">120 秒</option><option value="180">180 秒</option><option value="300">300 秒</option></select></div><div class="field full"><label>API Key</label><input class="input" id="aiKey" type="password" autocomplete="new-password" placeholder="留空保留当前密钥"></div></div><div class="sub" id="keyHint" style="margin-top:10px">当前密钥：读取中</div><div class="actions" style="margin-top:18px"><button class="btn primary" id="saveAiBtn">保存并立即生效</button><button class="btn secondary" id="testAiBtn">测试连接</button><button class="btn secondary" id="modelsBtn">读取模型</button></div><div class="log" id="aiResult" style="margin-top:16px">等待操作</div></div></section>
<section class="panel" id="panel-records"><div class="panel-head"><div><h2>预测档案</h2><p>查看服务器首次冻结结果与目标期结算。</p></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>彩种</th><th>目标期</th><th>来源 / 模型</th><th>名次与六码</th><th>结果</th></tr></thead><tbody id="recordsBody"></tbody></table></div></section>
<section class="panel" id="panel-security"><div class="panel-head"><div><h2>安全设置</h2><p>修改网页管理密码，不影响服务器 root 密码。</p></div></div><div class="card"><div class="form"><div class="field"><label>当前管理密码</label><input class="input" id="oldPassword" type="password"></div><div class="field"><label>新管理密码</label><input class="input" id="newPassword" type="password" minlength="8"></div></div><button class="btn primary" id="passwordBtn" style="margin-top:16px">更新管理密码</button></div></section>
</main></div></div>
<nav class="mobile"><button class="nav active" data-panel="overview">总览</button><button class="nav" data-panel="ai">AI</button><button class="nav" data-panel="records">档案</button><button class="nav" data-panel="security">安全</button></nav>
"""
    script = r"""
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const fmt=n=>n?new Date(n).toLocaleString('zh-CN',{hour12:false}):'—';
const toast=(m,e=false)=>{const t=$('toast');t.textContent=m;t.className='toast show'+(e?' error':'');setTimeout(()=>t.className='toast',2800)};
async function api(path,options={}){const r=await fetch(path,{cache:'no-store',...options,headers:{'X-Tianji-Admin':'1',...(options.headers||{})}});if(r.status===401){location.href='/admin';throw new Error('登录已过期')}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}
function setPanel(name){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id==='panel-'+name));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.panel===name));window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('.nav').forEach(x=>x.addEventListener('click',()=>setPanel(x.dataset.panel)));
function render(d){$('topStatus').textContent=d.health.worker==='ok'?'运行正常':'需要检查';$('topDot').style.background=d.health.worker==='ok'?'var(--good)':'var(--warn)';$('adminStats').innerHTML=`<div class="stat"><div class="label">API</div><div class="value good">${esc(d.health.status)}</div></div><div class="stat"><div class="label">数据库</div><div class="value good">${esc(d.health.database)}</div></div><div class="stat"><div class="label">后台任务</div><div class="value ${d.health.worker==='ok'?'good':'warn'}">${esc(d.health.worker)}</div></div><div class="stat"><div class="label">当前模型</div><div class="value">${d.ai.configured?esc(d.ai.model):'仅本机'}</div></div>`;$('adminLotteries').innerHTML=d.lotteries.map(x=>`<section class="card lottery"><div class="lottery-head"><div><h3>${esc(x.name)}</h3><div class="sub">最新期 ${esc(x.latest_period||'等待同步')} · ${fmt(x.synced_at_epoch_ms)}</div></div><div class="pill">目标期 ${esc(x.next_period||'待同步')}</div></div><div class="numbers">${(x.numbers||[]).map(n=>`<span class="num">${n}</span>`).join('')}</div><div class="sub">历史 ${x.draw_count} 期 · 最新档案 ${x.forecasts.length} 条</div></section>`).join('');$('runtimeLog').textContent=JSON.stringify({heartbeat:d.heartbeat,ai_errors:d.ai_errors},null,2);$('aiEnabled').checked=d.ai.enabled;$('aiEndpoint').value=d.ai.endpoint||'';$('aiModel').value=d.ai.model||'';$('aiTimeout').value=String(d.ai.timeout_seconds||120);$('keyHint').textContent='当前密钥：'+d.ai.api_key_hint;$('recordsBody').innerHTML=d.records.length?d.records.map(r=>`<tr><td>${esc(r.lottery_name)}</td><td>${esc(r.target_period)}</td><td>${r.source==='ai'?'AI':'本机'}<br><span class="sub">${esc(r.model)}</span></td><td>第 ${r.position+1} 名<br><span class="sub">${r.top6.join(' ')}</span></td><td>${r.top6_hit===true?'<span class="good">命中</span>':r.top6_hit===false?'<span class="bad">未中</span>':'待开奖'}</td></tr>`).join(''):'<tr><td colspan="5">暂无档案</td></tr>'}
async function load(){try{render(await api('/admin/api/state'))}catch(e){toast(e.message,true)}}
function payload(){return {enabled:$('aiEnabled').checked,endpoint:$('aiEndpoint').value.trim(),model:$('aiModel').value.trim(),api_key:$('aiKey').value||null,timeout_seconds:Number($('aiTimeout').value)}}
document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{const p=b.dataset.preset;if(p==='deepseek-pro'){$('aiEndpoint').value='https://api.deepseek.com/chat/completions';$('aiModel').value='deepseek-v4-pro'}else if(p==='deepseek-flash'){$('aiEndpoint').value='https://api.deepseek.com/chat/completions';$('aiModel').value='deepseek-v4-flash'}else if(p==='deepseek-custom'){$('aiEndpoint').value='https://api.deepseek.com/chat/completions';$('aiModel').focus()}else if(p==='openai'){$('aiEndpoint').value='https://api.openai.com/v1/responses';$('aiModel').value=''}}));
$('saveAiBtn').onclick=async()=>{try{await api('/admin/api/ai',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});$('aiKey').value='';toast('AI 配置已保存并立即生效');await load()}catch(e){toast(e.message,true)}};
$('testAiBtn').onclick=async()=>{try{$('aiResult').textContent='正在测试连接…';const d=await api('/admin/api/ai/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});$('aiResult').textContent=JSON.stringify(d,null,2);toast('连接测试完成')}catch(e){$('aiResult').textContent=e.message;toast(e.message,true)}};
$('modelsBtn').onclick=async()=>{try{$('aiResult').textContent='正在读取模型列表…';const d=await api('/admin/api/ai/models',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});$('modelList').innerHTML=d.models.map(m=>`<option value="${esc(m)}"></option>`).join('');$('aiResult').textContent=d.message+'\n'+d.models.join('\n');toast('模型列表已读取')}catch(e){$('aiResult').textContent=e.message;toast(e.message,true)}};
$('runBtn').onclick=async()=>{try{await api('/admin/api/run',{method:'POST'});toast('后台任务已开始');setTimeout(load,5000)}catch(e){toast(e.message,true)}};
$('passwordBtn').onclick=async()=>{try{await api('/admin/api/password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:$('oldPassword').value,new_password:$('newPassword').value})});$('oldPassword').value='';$('newPassword').value='';toast('管理密码已更新')}catch(e){toast(e.message,true)}};
$('logoutBtn').onclick=async()=>{await api('/admin/api/logout',{method:'POST'}).catch(()=>{});location.href='/admin'};
load();setInterval(load,30000);
"""
    return _document("天机控制台", body, script)
